import{_ as i,O as r,o as a,c as n,a as s,i as d,f as o}from"./chunks/framework.fmIt2z2h.js";const h=JSON.parse('{"title":"A.5　HV05 行动承接层（完整接口卡）","description":"","frontmatter":{"title":"A.5　HV05 行动承接层（完整接口卡）","xkChars":1880,"xkLessons":{"A.5":{"title":"A.5　HV05 行动承接层（完整接口卡）","lead":"HV05区分承接、成本、受益、停止权和六类责任；五条路线分别处理当前功能、历史留痕及两种跨期解释，任何路线都不产生无限承担义务。","explanation":["原文定位：第3832—3897行，原站定位/theory/appendix-a/a-05#section-a-5。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“承接能力不成为义务，CV不成为RS。”CV是实际执行、传导、维护、记录、照护或修复的载体，可能是人、岗位、程序、设施或制度；RS是具相应责任类型的主体。谁做、谁花成本、谁受益、谁有停止权、谁承担何种责任，必须分开。设施能传导数据，不因此成为道德/法律责任主体。[T-main；T-H2]","HV05-R0-carrier-responsibility-split依H2登记CV、同型成本承担者、受益者、停止权、RS、资源容量，止于当前分型和缺口。H2是操作分型规则，不是经验因果定律；R0可发现任务资源错配，但不把最可见执行者自动当主要决策、授权、受益或补救责任人。[T-main；T-H2]","HV05-R1-functional-carrier-effect要求合格G2支持指定载体替换、中断、补给、减载对预选功能结果的通道效应，并加CAUSAL/E4。只支持已测功能、容量、时延或损耗维度；某任务工时减少不证明总体负担减少，功能改善不产生继续牺牲义务或资源重配权限。[T-main；T-G2]","HV05-R2-intertemporal-reproduction要求当前通道已有G2支持，另有G3证明历史变量对后续承接/再生产具有当前表示之外的条件增量，仍加CAUSAL/E4。这里所说历史增量不是“发生过很久”或“旧规则还在”，而是固定当前表示等条件后，历史变量对指定后续结果仍提供相称增量。不能由此推出宿命、不可逆或归责。[T-main；T-G3]","HV05-R3-historical-carrier-trace是H5留痕路线，要求唯一预选具体载体和持久判据获supported，追加E4。它只支持该载体、可观察量与窗口内的持久留痕，并可向G3提交事先定义的历史变量候选；不单独证明未来路径、跨期再生产、修复窗口或行动资格。一个旧记录仍在，只是留痕线索，不是全部历史因果结论。[T-main；T-H5]","HV05-R4-carried-reproduction则是另一条跨期解释：G2已覆盖所声明后续结果/窗口，并依§4.5核当前能力、规则、资源或关系载体、多个周期保留/补给、实际接续与区分性因果材料。它不要求额外证明当前状态之外的G3增量，却也不能由一次功能效应直接外推长期。R2与R4是不同解释路线，不可互相吞掉。[T-main；T-G3]","五路一起给出精细上限：R0分型，R1有限功能效应，R2历史增量型跨期候选，R3持久留痕，R4载体传递型跨期候选。不能用R3最弱的长期字样取得R2/R4结论，也不能因为G3未支持就否定已有独立通道证据支持的载体传递。每路都不生成无限承担义务。[T-main]","九轴分别登记CV和RS。任务周期、维护积压、排班、恢复时滞、成本流向、替代路径和停止权各有材料；六类责任是行为、决策、授权、监督、受益、补救，不能压成一个“责任人”。若目标只问单项任务可用，不强制搜集所有私人负担；若声称总体减负，管理、待命、替代者条件与接续必须相称核查。[T-main]","低权限、非正式和不能退出承接者属于不可忽略的排除区。承接者可挑战任务、资源、成本、停止受限和归责，并取得原分配/归责链外的复核。获准回滚要撤错误任务资源或归责状态、实际恢复记录和任务状态并执行获准补救，不能把负担转给另一个没有发言权的人后称纠错结束。[T-main]","2005年三州Cash and Counseling报告把实际个人协助、支出计划、咨询、雇主与财政任务分开。这为承接劳动与协调管理分开提供真实项目设计材料，但报告两页不能证明总负担已消失或全部支持到达。这里只作R0式分工参照，不冒称正式G2/G3/H5支持。[P-CC]","39字段逐项研读（以下“原卡”保留该字段全部内容；“解读”明确其作用和不可替代的责任）。","01｜接口 ID（id）。原卡：HV05 解读：这是卡册内的短标识，追踪同一接口，不表示现实对象已被证明。 [T-main]","02｜限定 ID（qualified_id）。原卡：human_variable:HV05 解读：限定命名空间用于避免同名碰撞；引用此ID仍须携带对象和证据状态。 [T-main]","03｜名称（name）。原卡：行动承接层 解读：名称给出阅读入口，不是对具体人、群体或现实结构的自动标签。 [T-main]","04｜主张类型（claim_type）。原卡：H 解读：H表示人类实例/接口命题的角色；不能把它升级为形式证明或无条件世界规律。 [T-main]","05｜合同角色（contract_role）。原卡：human_variable_interface 解读：这是变量接口合同，规定怎样接入分析；字段存在不等于经验实例已经成立。 [T-main]","06｜命题（proposition）。原卡：执行、传导、维护、记录、照护与修复的承接载体CV必须和责任主体RS、成本承担者、受益者及停止权分别登记。 解读：这条命题必须连同后面的条件路由和上限理解，不能从一句话抽出无条件因果或规范结论。 [T-main]","07｜适用范围（scope）。原卡：需要持续行动、维护、照护或执行的人类结构 解读：范围列出可考察的任务领域，不代表范围内所有对象已获实证支持。 [T-main]","08｜暂停条件（pause_condition）。原卡：低权限执行者被默认归为主要责任人或承接能力被当作义务 解读：暂停针对所依赖的判断或采用；独立成立的描述可以保留，但不能继续使用失效前提。 [T-main]","09｜推理依赖（inferential_requires）。原卡：无（空集合） 解读：推理依赖提供命题成立所需的上游内容；上游的候选/支持状态必须原样传递，引用不自动升格。 [T-main]","10｜协议依赖（protocol_requires）。原卡：1. EVIDENCE；2. SOURCE 解读：协议依赖约束取证和表达方式；完成协议不单独证明经验命题为真。 [T-main]","11｜限定／特化（specializes）。原卡：1. H2 解读：本卡特化H2这一操作分型规则。它帮助区分CV与RS，不因分型正确而获得经验因果真值。 [T-main]","12｜适用对象引用（applies_to）。原卡：无（空集合） 解读：适用对象引用不能代替当前对象合同；空集合是明确登记，不是所有对象都可用。 [T-main]","13｜条件支持路由（conditional_support_routes）。原卡：1. route_id=HV05-R0-carrier-responsibility-split；；claim_level=descriptive_classification；；when=CV、同型成本承担者、受益者、停止权、RS、资源与容量可依H2分别登记。；；additional_inferential_requires=无（空集合）；；additional_protocol_requires=无（空集合）；；allowed_conclusion=登记当前承接载体、任务、成本、容量、停止权、责任类型与承接缺口。；；result_ceiling=只到当前分型与缺口描述；承接能力不成为义务，CV不成为RS。；2. route_id=HV05-R1-functional-carrier-effect；；claim_level=conditional_effect；；when=符合资格的G2-instance显示指定载体替换、中断、补给或减载对预选功能结果有超过阈值的通道效应。；；additional_inferential_requires=G2-instance；；additional_protocol_requires=CAUSAL、E4；；allowed_conclusion=登记指定载体在已测功能、容量、时延或损耗维度上的候选承接效应。；；result_ceiling=未测维度保持未知；功能效应不得直接生成责任、牺牲义务或资源重配授权。；3. route_id=HV05-R2-intertemporal-reproduction；；claim_level=intertemporal_explanation；；when=当前承接通道已有G2-instance支持，且G3-instance显示其历史变量对后续承接或再生产结果具有条件增量。；；additional_inferential_requires=G2-instance、G3-instance；；additional_protocol_requires=CAUSAL、E4；；allowed_conclusion=登记指定窗口与载体内、当前状态之外的历史增量型跨期承接或再生产候选。；；result_ceiling=不推出历史宿命、不可逆、责任归属或继续承担义务。；4. route_id=HV05-R3-historical-carrier-trace；；claim_level=descriptive_classification；；when=H5-instance对唯一预选的具体载体与持久判据取得supported。；；additional_inferential_requires=H5-instance；；additional_protocol_requires=E4；；allowed_conclusion=登记指定载体、留痕可观察量与窗口内的持久人类留痕，并向G3-instance提交预先定义的历史变量候选。；；result_ceiling=H5-instance不证明未来路径效应、跨期再生产、修复窗口、责任或行动；这些结论分别依载体或历史增量路线、结果合同与规范程序取证。；5. route_id=HV05-R4-carried-reproduction；；claim_level=intertemporal_explanation；；when=符合资格的G2-instance支持指定承接通道在所声明后续结果与窗口内的效应，且依§4.5核实当前能力、规则、资源或关系载体、多个周期的保留或补给、实际接续及区分性因果材料。；；additional_inferential_requires=G2-instance；；additional_protocol_requires=CAUSAL、E4；；allowed_conclusion=登记指定载体、周期和结果内的载体传递型跨期承接或再生产候选。；；result_ceiling=不登记当前状态之外的历史增量，不由一次功能效应外推长期，不从承接事实产生继续承担义务或授权。 解读：五路逐条独立：R0当前分型；R1 G2有限功能；R2 G2＋G3历史增量；R3 H5唯一载体/持久判据留痕；R4 G2后续窗口＋当前载体跨周期接续。不能混拿条件与结论。 [T-main]","14｜允许推论（allowed_inference）。原卡：1. 承接缺口2. 任务资源错配3. 责任分流 解读：这是允许谈论的结论方向；实际达到哪一项、到什么强度，仍由所选路由及材料限定。 [T-main]","15｜禁止跳跃（prohibited_leap）。原卡：1. 最可见者等于主要责任人；2. 能承担所以应承担；3. 仅凭设施或程序执行功能就赋予责任；组织责任另据主体资格与具体规则 解读：这些是常见越界，不是换个措辞就能避开；检查实际推断和后续使用，而非只看用词。 [T-main]","16｜九轴尺度画像（scale_profile）。原卡：SP=<A,X,T,O,C,R,I,N,J>；A=聚合层次：单项任务或承接事件、载体个案、承接总体、成本容量分布及聚合规则；X=空间范围：岗位现场、团队或组织边界、数字系统与跨域服务范围；T=时间跨度：任务周期、维护窗口、恢复时滞与责任有效期；O=组织层级：执行角色、团队、组织、制度至治理生态；C=因果层次：执行事件、任务—资源互动机制、中观承接结构、制度责任安排与系统条件；R=观察分辨率：原始任务日志、承接序列、载体个案、成本容量分布、绩效指标与摘要，并登记压缩损失；I=影响范围：直接承接者、服务依赖者、间接受益或成本位置、二阶外溢、跨域与代际影响；N=网络拓扑范围：承接依赖、替代路径、单点瓶颈与跨域服务网络；J=管辖与授权范围：任务分配、停止、资源调整、归责与补救分别登记授权；CV与RS分别登记尺度 解读：九轴逐项登记；尤其影响范围I不产生管辖权限J，观察分辨率R降低时须保留压缩损失。 [T-main]","17｜有效对象（effective_object）。原卡：实际执行、传导、维护、记录、照护或修复的人、岗位、程序、设施或制度 解读：这是该接口对应的对象描述；若选择低门槛描述路由，不能把名称中的功能含义当作因果已证。 [T-main]","18｜跨尺度保持项（scale_invariants）。原卡：1. CV不等于RS；2. 成本与受益分别登记；3. 停止权 解读：保持项是迁移时须守住的比较责任，不是宣称所有尺度上的变量数值不变。 [T-main]","19｜升格必补项（required_scale_additions）。原卡：1. 任务聚合；2. 代表和委托；3. 六类责任；4. 外部成本 解读：升格不是把原表复制放大。新增总体、接口和责任位置等材料未齐时，限制依赖它们的结论。 [T-main]","20｜随尺度改变项（changing_semantics）。原卡：1. 承接载体和责任主体可随层级改变 解读：同一词在对象或尺度改变后可能变义，应重建对应而非假定原含义原样适用。 [T-main]","21｜不适用对象（non_applicable_objects）。原卡：1. 无主体行动、责任或维护要求的非人过程 解读：不适用约束防止人类规范、责任和体验接口被无条件投射；不等于否认其他理论可研究这些对象。 [T-main]","22｜禁止升格（forbidden_elevation）。原卡：1. 个体承接直接等于组织责任 解读：局部向整体的推断必须另证；影响广、名称大或形式相似都不能补代表性和授权。 [T-main]","23｜状态集合（state）。原卡：1. 充足；2. 脆弱；3. 过载；4. 断裂；5. 替代 解读：状态是待证描述分类，不是给人评分的成熟阶梯；状态改变须有窗口、依据与版本。 [T-main]","24｜可观测项（observables）。原卡：1. 任务实际执行、维护、记录与修复日志；2. 资源、容量、时间和成本流向；3. 停止权、替代安排与承接转移记录；4. 决策、授权、监督、受益与补救依据 解读：可观测线索回答到哪里找材料；单一线索的存在还不是完整机制或因果效应的证明。 [T-main]","25｜证据要求（evidence）。原卡：1. 任务流；2. 工时与资源；3. 维护记录；4. 停止和拒绝记录；5. 若目标涉及总体负担，分别核管理、待命、替代者条件及接续；单项任务判断不强制全部采集 解读：单项任务证据不强制无限扩张；若主张总体负担，才另核管理、待命、替代者条件与接续。证据强度须与所问终点相称。 [T-main]","26｜输入依赖与接口内容（input_dependencies）。原卡：1. 生成需求2. 资源3. 授权4. 角色 解读：资源、角色、授权和生成需求是应核输入，不是把“有人能做”当作已获得其同意或义务。 [T-main]","27｜输出效应与变量流（output_effects）。原卡：1. 实现状态转移2. 成本分布3. 结构负荷 解读：变量流说明哪些下游判断可能依赖本接口；传递引用不保证下游结论、实际修复或授权成立。 [T-main]","28｜时间窗与时滞（time_window_and_lag）。原卡：登记排班、维护周期、积压与恢复时滞 解读：发生、观察、执行和效果到达可能不同时；窗口外延不能由短期材料自动认证。 [T-main]","29｜不确定性（uncertainty）。原卡：记录隐性劳动、非正式照护和边界外成本 解读：把不确定性指向具体材料和位置，不能只写一个总置信分而掩盖根本未覆盖的位置。 [T-main]","30｜局部排除区（local_exclusion_zone）。原卡：低权限、非正式与不可退出承接者 解读：排除区限制当前推断覆盖，不是把这些人或事实从世界删除；安全不可得也不是同意或无问题。 [T-main]","31｜受影响位置（affected_positions）。原卡：1. 承接者；2. 受益者；3. 被服务者；4. 替代者 解读：同时登记直接和间接受影响者；可见成员不代表全部成本承担者。 [T-main]","32｜承接载体（carrier）。原卡：1. 人员；2. 岗位；3. 程序；4. 设施；5. 制度 解读：载体是实际承载的结构或过程；载体名称、建设完成和所需功能到达是不同证据。 [T-main]","33｜责任主体（responsible_subject）。原卡：1. 行为责任者；2. 决策责任者；3. 授权责任者；4. 监督责任者；5. 受益责任者；6. 补救责任者 解读：六类责任分别依据实际规则、事实和主体资格判定。一个人可能承担多类，但不能从低权限执行事实自动推全部责任。 [T-main]","34｜规范地位（normative_status）。原卡：承接事实不产生继续承担义务 解读：按卡片区分描述、规范和桥接身份。事实成立不独立决定价值排序，规范理由不自动证明经验效果。 [T-main]","35｜判断上限（judgment_ceiling）。原卡：R0限于承接与责任分型；R1限于所识别的载体功能效应；R3限于H5支持的持久留痕；R4依§4.5与覆盖后续窗口的通道证据解释载体型再生产；R2另有G3时才解释当前表示之外的历史增量。材料和窗口各自限定，不以任一路线代替其余路线，也不产生无限承担义务。 解读：特别防三种偷换：H5留痕不等于G3历史增量；一次G2功能不等于跨期再生产；G3未支持不自动否定有独立证据的R4载体传递。 [T-main]","36｜行动上限（action_ceiling）。原卡：本变量只生成CV、RS、成本、容量、停止权与承接缺口描述，以及减载、补资源或重分配需求，不授权任务调整、资源配置、归责或保护；任何现实调整须另过C12、运行时显式N前提、J授权与O程序 解读：接口本身不产生现实处置权；实际动作另核选择、C12、显式N、有效J、O及保护和期限。 [T-main]","37｜反例（counterexamples）。原卡：1. 最可见的低权限执行者不是决策、授权或受益责任主体；2. 自动化设施承担传导任务但不能承担道德或法律责任 解读：用反例限定无条件外推；反例可能要求缩小范围或重新取证，不自动否定所有有限用法。 [T-main]","38｜申诉（appeal）。原卡：依appeal_and_rollback_rule，承接者可经安全可达、反报复通道挑战任务、资源、成本、停止权受限和归责，并触发与原任务分配或归责链独立的复核 解读：申诉要安全可达、免于报复并能触发独立复核；只留一个名称不代表有权改变错误。 [T-main]","39｜回滚（rollback）。原卡：依appeal_and_rollback_rule，获准回滚时，由指定责任人在规定时限内撤销错误任务、资源或归责状态，实际恢复先前任务与记录状态并执行经授权补救，保留版本与完成验证 解读：在有效授权内实际撤销错误效力、纠正下游并验证完成；文档改字不等于权利资源恢复到当事人。 [T-main]"],"argumentSteps":["先按H2分开CV、RS、成本承担者、受益者和停止权。","R0描述当前资源容量与缺口，保留隐性劳动。","R1用G2核指定功能维度，不把局部改善推成总减负。","R3用H5核唯一载体留痕；未来效应需另有路线。","跨期R2须当前外历史增量G3；R4以当前载体跨周期接续与后续通道证据成立。","分别核责任、规范和权限，保护承接者申诉与停止。","获准纠错后实际撤错误任务归责并验证补救到达。"],"distinctions":[{"leftTitle":"CV承接载体","leftText":"实际执行或维持功能。","rightTitle":"RS责任主体","rightText":"具体责任类型与资格另核。"},{"leftTitle":"R3持久留痕","leftText":"H5支持载体上的保存。","rightTitle":"R2历史增量","rightText":"G3检验当前表示之外的后续增量。"},{"leftTitle":"R4载体传递","leftText":"当前载体经周期保留补给与实际接续。","rightTitle":"一次功能效应","rightText":"不自动证明长期再生产。"},{"leftTitle":"执行劳动减少","leftText":"某项任务由替代者接续。","rightTitle":"总体负担减少","rightText":"管理、待命、费用和替代条件需另核。"}],"boundaries":["原卡反例：最可见的低权限执行者不是决策、授权或受益责任主体。","原卡反例：自动化设施传导任务不使它承担道德法律责任。","教学反例：旧文件保存十年便宣称已证明未来再生产和不可逆路径。","原文边界：能承担不等于应承担；功能效应不赋予任务或资源调整权。"],"questions":["谁最忙是否就主要负责？","H5已支持留痕能否推出未来再生产？","没有G3是否一切跨期承接解释都不成立？","帮忙后执行工时减少，能否承认局部成果？"],"diagramPath":"/reading-assets/S-A-5/figures/hv05-roles.png","caseLinks":[{"title":"三州Cash and Counseling的工作分工","href":"https://aspe.hhs.gov/sites/default/files/migrated_legacy_files/41521/adultpcw.pdf"}],"caseNotes":[{"title":"三州Cash and Counseling的工作分工","text":"2005年报告所述美国Arkansas、New Jersey、Florida项目，把个人协助与支出计划、咨询和财政/雇主支持分别描述。","sourceLabel":"Cash and Counseling：Effect of Consumer Direction on Adults’ Personal Care and Well-Being in Arkansas, New Jersey and Florida","sourceUrl":"https://aspe.hhs.gov/sites/default/files/migrated_legacy_files/41521/adultpcw.pdf","sourceLocator":"2005-05-16报告，印刷7—8页（PDF19—20），支出计划与Counseling and Fiscal Services","boundary":"设计分工不证明所有支持实际到达或总负担消失；不是正式G/H实例，不作现实个人照护方案。","href":"https://aspe.hhs.gov/sites/default/files/migrated_legacy_files/41521/adultpcw.pdf"}],"sourceRefs":[{"section":"A.5","start_line":3832,"end_line":3897,"startLine":3832,"endLine":3897}],"outputId":"section-a-5","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：一个任务减少与总负担未定","text":"人工照护任务原执行4小时、管理1小时、待命2小时。替代者接走4小时执行，原承担者仍管理和待命。可承认执行减少4小时；若同一口径简单计时，原承担者仍有3小时，不是零。现实总体负担还包括时段重叠、心理和资源等，不可仅把7与3当完整福利量。","assumptions":"工时全部人工且设为不重叠，只演示任务/总体终点区别。","boundary":"不能因剩3小时否认已减4小时，也不能以接续必要要求原承担者无限留守。"},{"title":"教学构造：三种历史说法分别取证","text":"虚构机构旧培训记录仍保存，这是留痕候选；当前受训人员每期把技能用于服务并获得补给，是载体接续候选；在相同当前技能、规则、资源表示下，不同历史路径仍改善后续预测或识别，是历史增量候选。三者分别需H5、R4所需G2/载体周期材料、R2所需G2/G3，不能拿保存记录一项同时认证三种。","assumptions":"机构、材料及比较均为人工，无正式实例结果。","boundary":"“候选”不是supported；当前表示之外的增量与由当前载体传递不互相排斥，也不互相代证。"}],"counterexamples":[{"identity":"source_counterexample","text":"原卡反例：最可见的低权限执行者不是决策、授权或受益责任主体。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原卡反例：自动化设施传导任务不使它承担道德法律责任。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：旧文件保存十年便宣称已证明未来再生产和不可逆路径。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：能承担不等于应承担；功能效应不赋予任务或资源调整权。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"谁最忙是否就主要负责？","answer":"不；CV、成本与六类RS分别核，不能由可见执行推决策授权责任。","basis":"H2及本卡禁止跳跃。"},{"question":"H5已支持留痕能否推出未来再生产？","answer":"不能；R3只留痕，跨期按R2或R4另取证。","basis":"R3上限。"},{"question":"没有G3是否一切跨期承接解释都不成立？","answer":"不是；R4以当前载体、多周期接续及覆盖后续的G2证据解释载体传递，但不能冒称G3增量。","basis":"R4与R2区别。"},{"question":"帮忙后执行工时减少，能否承认局部成果？","answer":"能；按指定任务与条件承认，若问总体负担则另核管理待命替代者条件。","basis":"evidence第5项。"}],"figures":[{"path":"/reading-assets/S-A-5/figures/hv05-roles.png","alt":"承接载体、成本承担者、受益者、停止权与六类责任分别登记，不由能做推出应做。","caption":"据A.5 H2分型。"},{"path":"/reading-assets/S-A-5/figures/hv05-routes.png","alt":"R0分型、R1G2功能、R2G2加G3增量、R3H5留痕、R4G2和载体接续；不得互换。","caption":"据A.5五条完整路由及§4.5。"},{"path":"/reading-assets/S-A-5/figures/hv05-burden.png","alt":"执行、管理、待命、费用与替代者条件分别核；单项成果可成立，整体主张需整体材料。","caption":"据A.5证据第5项；人工4/1/2小时算例见正文。"}],"diagramBrief":"三图分别分离承接责任、五路证据、局部与总体负担。路线编号不是阶段，不能逐级升级；图只指向各自证据要求。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"本单元涉及方法判断，真实来源仅支持所列事实；图与教学构造分别保留其身份。"},"openQuestions":["本题没有合格G2/G3/H5实例记录，五路解释不签发任何supported。","真实减负、持久接续、主体责任及行动权限需要按所选结果和窗口独立核验。"],"taskId":"S-A-5","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§A.5，第3832—3897行","claim_support":["HV05全部39字段及R0—R4五路，任务与总体负担终点。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-H2","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§7.1，第1469—1485行","claim_support":["H2操作分型，不自带经验真值。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-G2","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§4.4，第610—619行","claim_support":["指定载体通道效应。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-G3","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§4.5，第620—641行","claim_support":["历史增量与当前载体传递的不同路线。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-H5","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§4.2，第586—601行","claim_support":["H5唯一载体、结果家族与持久判据。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"P-CC","title":"Cash and Counseling：Effect of Consumer Direction on Adults’ Personal Care and Well-Being in Arkansas, New Jersey and Florida","url":"https://aspe.hhs.gov/sites/default/files/migrated_legacy_files/41521/adultpcw.pdf","source_type":"primary","version_or_date":"2005-05-16","locator":"2005-05-16报告，印刷7—8页（PDF19—20），支出计划与Counseling and Fiscal Services","claim_support":["三州项目分列个人协助、支出计划、雇主协助、咨询和财政管理支持。"],"limits":["本人读取既有原PDF19—20完整页；本次在线回取403，依据已保存原件核验；仅用历史设计分工，不证明支持全部落实、协调负担消失或任何G/H实例正式成立，不作当前照护或法律建议。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-A-5/lecture.md","sourcesPath":"/reading-assets/S-A-5/sources.json","sourceSlicePath":"/reading-assets/S-A-5/source/S-A-5.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-A-5/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-a/a-05.md","filePath":"theory/appendix-a/a-05.md"}'),l={name:"theory/appendix-a/a-05.md"};function c(_,t,u,p,b,m){const e=r("SectionLesson");return a(),n("div",null,[t[0]||(t[0]=s('<div class="theory-source"><h1 id="section-a-5" tabindex="-1"><span class="xk-num"><span class="xk-num__n">A.5</span><span class="xk-num__gap">　</span></span>HV05 行动承接层（完整接口卡） <a class="header-anchor" href="#section-a-5" aria-label="Permalink to &quot;A.5　HV05 行动承接层（完整接口卡） {#section-a-5}&quot;">​</a></h1><p>A. 身份、命题与适用范围</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>接口 ID（id）</td><td>HV05</td></tr><tr><td>限定 ID（qualified_id）</td><td>human_variable:HV05</td></tr><tr><td>名称（name）</td><td>行动承接层</td></tr><tr><td>主张类型（claim_type）</td><td>H</td></tr><tr><td>合同角色（contract_role）</td><td>human_variable_interface</td></tr><tr><td>命题（proposition）</td><td>执行、传导、维护、记录、照护与修复的承接载体CV必须和责任主体RS、成本承担者、受益者及停止权分别登记。</td></tr><tr><td>适用范围（scope）</td><td>需要持续行动、维护、照护或执行的人类结构</td></tr><tr><td>暂停条件（pause_condition）</td><td>低权限执行者被默认归为主要责任人或承接能力被当作义务</td></tr></tbody></table></div><p>B. 正式依赖与结论边界</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>推理依赖（inferential_requires）</td><td>无（空集合）</td></tr><tr><td>协议依赖（protocol_requires）</td><td>1. EVIDENCE<br>2. SOURCE</td></tr><tr><td>限定／特化（specializes）</td><td>1. H2</td></tr><tr><td>适用对象引用（applies_to）</td><td>无（空集合）</td></tr><tr><td>条件支持路由（conditional_support_routes）</td><td>1. route_id=HV05-R0-carrier-responsibility-split；<br>claim_level=descriptive_classification；<br>when=CV、同型成本承担者、受益者、停止权、RS、资源与容量可依H2分别登记。；<br>additional_inferential_requires=无（空集合）；<br>additional_protocol_requires=无（空集合）；<br>allowed_conclusion=登记当前承接载体、任务、成本、容量、停止权、责任类型与承接缺口。；<br>result_ceiling=只到当前分型与缺口描述；承接能力不成为义务，CV不成为RS。<br>2. route_id=HV05-R1-functional-carrier-effect；<br>claim_level=conditional_effect；<br>when=符合资格的G2-instance显示指定载体替换、中断、补给或减载对预选功能结果有超过阈值的通道效应。；<br>additional_inferential_requires=G2-instance；<br>additional_protocol_requires=CAUSAL、E4；<br>allowed_conclusion=登记指定载体在已测功能、容量、时延或损耗维度上的候选承接效应。；<br>result_ceiling=未测维度保持未知；功能效应不得直接生成责任、牺牲义务或资源重配授权。<br>3. route_id=HV05-R2-intertemporal-reproduction；<br>claim_level=intertemporal_explanation；<br>when=当前承接通道已有G2-instance支持，且G3-instance显示其历史变量对后续承接或再生产结果具有条件增量。；<br>additional_inferential_requires=G2-instance、G3-instance；<br>additional_protocol_requires=CAUSAL、E4；<br>allowed_conclusion=登记指定窗口与载体内、当前状态之外的历史增量型跨期承接或再生产候选。；<br>result_ceiling=不推出历史宿命、不可逆、责任归属或继续承担义务。<br>4. route_id=HV05-R3-historical-carrier-trace；<br>claim_level=descriptive_classification；<br>when=H5-instance对唯一预选的具体载体与持久判据取得supported。；<br>additional_inferential_requires=H5-instance；<br>additional_protocol_requires=E4；<br>allowed_conclusion=登记指定载体、留痕可观察量与窗口内的持久人类留痕，并向G3-instance提交预先定义的历史变量候选。；<br>result_ceiling=H5-instance不证明未来路径效应、跨期再生产、修复窗口、责任或行动；这些结论分别依载体或历史增量路线、结果合同与规范程序取证。<br>5. route_id=HV05-R4-carried-reproduction；<br>claim_level=intertemporal_explanation；<br>when=符合资格的G2-instance支持指定承接通道在所声明后续结果与窗口内的效应，且依§4.5核实当前能力、规则、资源或关系载体、多个周期的保留或补给、实际接续及区分性因果材料。；<br>additional_inferential_requires=G2-instance；<br>additional_protocol_requires=CAUSAL、E4；<br>allowed_conclusion=登记指定载体、周期和结果内的载体传递型跨期承接或再生产候选。；<br>result_ceiling=不登记当前状态之外的历史增量，不由一次功能效应外推长期，不从承接事实产生继续承担义务或授权。</td></tr><tr><td>允许推论（allowed_inference）</td><td>1. 承接缺口2. 任务资源错配3. 责任分流</td></tr><tr><td>禁止跳跃（prohibited_leap）</td><td>1. 最可见者等于主要责任人<br>2. 能承担所以应承担<br>3. 仅凭设施或程序执行功能就赋予责任；组织责任另据主体资格与具体规则</td></tr></tbody></table></div><p>C. 九轴尺度与对象合同</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>九轴尺度画像（scale_profile）</td><td>SP=&lt;A,X,T,O,C,R,I,N,J&gt;；A=聚合层次：单项任务或承接事件、载体个案、承接总体、成本容量分布及聚合规则；X=空间范围：岗位现场、团队或组织边界、数字系统与跨域服务范围；T=时间跨度：任务周期、维护窗口、恢复时滞与责任有效期；O=组织层级：执行角色、团队、组织、制度至治理生态；C=因果层次：执行事件、任务—资源互动机制、中观承接结构、制度责任安排与系统条件；R=观察分辨率：原始任务日志、承接序列、载体个案、成本容量分布、绩效指标与摘要，并登记压缩损失；I=影响范围：直接承接者、服务依赖者、间接受益或成本位置、二阶外溢、跨域与代际影响；N=网络拓扑范围：承接依赖、替代路径、单点瓶颈与跨域服务网络；J=管辖与授权范围：任务分配、停止、资源调整、归责与补救分别登记授权；CV与RS分别登记尺度</td></tr><tr><td>有效对象（effective_object）</td><td>实际执行、传导、维护、记录、照护或修复的人、岗位、程序、设施或制度</td></tr><tr><td>跨尺度保持项（scale_invariants）</td><td>1. CV不等于RS<br>2. 成本与受益分别登记<br>3. 停止权</td></tr><tr><td>升格必补项（required_scale_additions）</td><td>1. 任务聚合<br>2. 代表和委托<br>3. 六类责任<br>4. 外部成本</td></tr><tr><td>随尺度改变项（changing_semantics）</td><td>1. 承接载体和责任主体可随层级改变</td></tr><tr><td>不适用对象（non_applicable_objects）</td><td>1. 无主体行动、责任或维护要求的非人过程</td></tr><tr><td>禁止升格（forbidden_elevation）</td><td>1. 个体承接直接等于组织责任</td></tr></tbody></table></div><p>D. 状态、证据与变量流</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>状态集合（state）</td><td>1. 充足<br>2. 脆弱<br>3. 过载<br>4. 断裂<br>5. 替代</td></tr><tr><td>可观测项（observables）</td><td>1. 任务实际执行、维护、记录与修复日志<br>2. 资源、容量、时间和成本流向<br>3. 停止权、替代安排与承接转移记录<br>4. 决策、授权、监督、受益与补救依据</td></tr><tr><td>证据要求（evidence）</td><td>1. 任务流<br>2. 工时与资源<br>3. 维护记录<br>4. 停止和拒绝记录<br>5. 若目标涉及总体负担，分别核管理、待命、替代者条件及接续；单项任务判断不强制全部采集</td></tr><tr><td>输入依赖与接口内容（input_dependencies）</td><td>1. 生成需求2. 资源3. 授权4. 角色</td></tr><tr><td>输出效应与变量流（output_effects）</td><td>1. 实现状态转移2. 成本分布3. 结构负荷</td></tr><tr><td>时间窗与时滞（time_window_and_lag）</td><td>登记排班、维护周期、积压与恢复时滞</td></tr><tr><td>不确定性（uncertainty）</td><td>记录隐性劳动、非正式照护和边界外成本</td></tr><tr><td>局部排除区（local_exclusion_zone）</td><td>低权限、非正式与不可退出承接者</td></tr><tr><td>受影响位置（affected_positions）</td><td>1. 承接者<br>2. 受益者<br>3. 被服务者<br>4. 替代者</td></tr></tbody></table></div><p>E. 承接、责任、规范、上限与纠错</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>承接载体（carrier）</td><td>1. 人员<br>2. 岗位<br>3. 程序<br>4. 设施<br>5. 制度</td></tr><tr><td>责任主体（responsible_subject）</td><td>1. 行为责任者<br>2. 决策责任者<br>3. 授权责任者<br>4. 监督责任者<br>5. 受益责任者<br>6. 补救责任者</td></tr><tr><td>规范地位（normative_status）</td><td>承接事实不产生继续承担义务</td></tr><tr><td>判断上限（judgment_ceiling）</td><td>R0限于承接与责任分型；R1限于所识别的载体功能效应；R3限于H5支持的持久留痕；R4依§4.5与覆盖后续窗口的通道证据解释载体型再生产；R2另有G3时才解释当前表示之外的历史增量。材料和窗口各自限定，不以任一路线代替其余路线，也不产生无限承担义务。</td></tr><tr><td>行动上限（action_ceiling）</td><td>本变量只生成CV、RS、成本、容量、停止权与承接缺口描述，以及减载、补资源或重分配需求，不授权任务调整、资源配置、归责或保护；任何现实调整须另过C12、运行时显式N前提、J授权与O程序</td></tr><tr><td>反例（counterexamples）</td><td>1. 最可见的低权限执行者不是决策、授权或受益责任主体<br>2. 自动化设施承担传导任务但不能承担道德或法律责任</td></tr><tr><td>申诉（appeal）</td><td>依appeal_and_rollback_rule，承接者可经安全可达、反报复通道挑战任务、资源、成本、停止权受限和归责，并触发与原任务分配或归责链独立的复核</td></tr><tr><td>回滚（rollback）</td><td>依appeal_and_rollback_rule，获准回滚时，由指定责任人在规定时限内撤销错误任务、资源或归责状态，实际恢复先前任务与记录状态并执行经授权补救，保留版本与完成验证</td></tr></tbody></table></div></div>',1)),d(e,{section:"A.5"}),t[1]||(t[1]=o("div",{class:"theory-source"},null,-1))])}const R=i(l,[["render",c]]);export{h as __pageData,R as default};
